/// Sets every function's example; an unknown name is recorded as a
/// registry conflict (a stale table), which the registry tests report.
pub(crate) fn apply(r: &mut Registry) {
    for (name, example) in EXAMPLES {
        r.set_example(name, example);
    }
}
